import React, { useEffect, useState, useRef } from "react";
import { useLocation } from 'react-router-dom';
import axios from "axios";
import '../../component/grid.css';
import '../../component/style.css';
import styles from '../home/home.module.css';
import CheckScreenSize from '../../component/checkScreenSize';
import { editTenTruyen } from "../../component/editTenTruyen";

const Search = () => {
    const location = useLocation();
    const [truyens, setTruyens] = useState([]);
    const [tuKhoa, setTuKhoa] = useState('');
    const mobileRefs = useRef([]);

    CheckScreenSize(mobileRefs);

    // Lấy query string từ URL (?keyword=...)
    useEffect(() => {
        const query = new URLSearchParams(location.search);
        const keyword = query.get('keyword') || '';
        setTuKhoa(keyword);

        const fetchSearchResults = async () => {
            try {
                const response = await axios.get(`http://localhost:3001/truyens/timkiem/tentruyen?keyword=${keyword}`);
                setTruyens(response.data);
            } catch (error) {
                console.error("Lỗi khi tìm kiếm truyện:", error);
            }
        };

        if (keyword.trim() !== '') {
            fetchSearchResults();
        } else {
            setTruyens([]);
        }
    }, [location]);

    if (tuKhoa.trim() === '') {
        return <h3 style={{ margin: '20px' }}>Vui lòng nhập từ khóa để tìm kiếm truyện.</h3>;
    }

    return (
        <div className="grid wide list-product" style={{ marginTop: 25 }}>
            <h2 style={{ marginBottom: 15 }}>Kết quả tìm kiếm cho: <i>"{tuKhoa}"</i></h2>
            <div className={`row ${styles['list-item']}`}>
                {truyens.length > 0 ? (
                    truyens.map((truyen, index) => (
                        <div
                            key={truyen.id}
                            className={`col l-2-4 m-3 c-4 checkSizeMobile ${styles['col']}`}
                            ref={(el) => (mobileRefs.current[index] = el)}
                        >
                            <div className={styles['product']}>
                                <a href={`/truyen/${truyen.id}`} className="a-black">
                                    <div className={styles['product-img']}>
                                        <img src={truyen.anhtruyen} alt={truyen.tentruyen} className={styles['product-img']} />
                                    </div>
                                    <h4 className={styles['product-name']}>{editTenTruyen(truyen.tentruyen)}</h4>
                                    <div className={styles['product-price']}>
                                        <span className={styles['current-price']}><b>{Number(truyen.giaban).toLocaleString()}₫</b></span>
                                        {truyen.giagoc && <span className={styles['original-price']}><s><b>{Number(truyen.giagoc).toLocaleString()}₫</b></s></span>}
                                    </div>
                                </a>
                            </div>
                        </div>
                    ))
                ) : (
                    <div style={{ padding: '10px 0 20px' }}>
                        <i>Không tìm thấy truyện nào với từ khóa "<b>{tuKhoa}</b>"</i>
                    </div>
                )}
            </div>
        </div>
    );
}

export default Search;
